      const distToEdge = Math.min(x, y, 30 - 1 - x, 30 - 1 - y)
      // Cast-shadow signature: dark, warm-tinted (r > b), within the boundary ring.
      return distToEdge < 3 ? [120, 90, 60] : [235, 230, 225]
